B=[['希腊 pais，属格 paidos；词干 paid-','儿童；孩子']]
PEDIATRIC=B+[['希腊来源 paid- 儿童 + 医疗构件 -iatric','以儿童为对象的医疗'],['英语 pediatric／paediatric','儿科的；儿童医疗的']]
PEDIATRICS=A(PEDIATRIC,'英语 pediatric／paediatric + 学科词尾 -s → pediatrics／paediatrics','儿科学；儿科医疗')
PEDIATRICIAN=A(PEDIATRIC,'英语 pediatric／paediatric + -ian → pediatrician／paediatrician','从事儿科医疗的医生')
GOG=B+[['希腊 paid- + agogos 引导者 → paidagogos','带领、照管儿童的人；古代常指陪孩子上学的奴隶'],['拉丁 paedagogus → 法语 pedagogue 等 → 中古英语 pedagoge','儿童教师、教导者']]
GOGY=B+[['希腊 paidagogos → paidagogia','儿童教导者 → 教导、教育'],['拉丁 paedagogia／法语 pédagogie → 英语 pedagogy','教学理论、教学方法']]
PEDANT=[['意大利语 pedante〔更早来源未定〕','教师、学究'],['法语 pédant 或直接意大利语 → 英语 pedant','早期指教师；后来多指过分卖弄知识、拘泥细节的人']]
ORTHO=B+[['希腊 orthos 正、直 + paideia 儿童教养','供近代构词使用的两个希腊构件'],['法语 orthopédie → orthopédique','最初围绕儿童体态、肢体矫形的医学名称'],['英语 orthopaedic／orthopedic','骨科的；范围后来不限于儿童']]
ORTHOPEDICS=A(ORTHO,'英语 orthopedic／orthopaedic → orthopedics／orthopaedics','骨科学、骨科')
ORTHOPEDIST=B+[['希腊来源构件 → 法语 orthopédie → 英语 orthopedy／orthopaedy','近代形成的矫形医学名称'],['英语 orthopedy 词干 + -ist → orthopedist／orthopaedist','骨科医师']]
PHIL=B+[['希腊来源 paid- 儿童 + -philia 吸引、喜爱','近代医学构词材料'],['德语医学术语 Pädophilie → 英语 pedophilia／paedophilia','针对未进入青春期儿童的持续性性吸引']]
AAOS='https://www.orthoinfo.org/treatment/orthopaedics/'
AAP='https://healthychildren.org/english/ages-stages/prenatal/decisions-to-make/pages/a-pediatricians-training.aspx'
APA='https://dictionary.apa.org/pedophilia'
